local cp=bp.buff[Vo]or 0
if(bp.sold or 0)>0 then
if bp.id~=Ko then
Zo=Zo+1
end
if cp>0 then
if bp.id==Ko then
Wo=Wo+1
else
Yo=Yo+1
end
_o=math.max(_o,cp)
end
elseif cp>0 then
Xo=Xo+1
end
end
if Wo>0 and Xo==0 and(not Uo or Wo>Uo)then
To,Uo={name=Vo,other=Yo,otherAfter=Zo,top=_o},Wo
end
