if Lo.family==Lde[2111]then
local up,vp
for wp,yp in pairs(Jo.foeBuffs)do
if yp.first>=No-1 and yp.near>0 and(Oo[wp]or yp.near>=0.5*yp.n)and(not ep or pb.nearCast(Jo,Ko,yp.onsets)>0)then
local zp=yp.near+(Oo[wp]and 1e6 or 0)+(ep and pb.nearCast(Jo,Ko,yp.onsets)*1000 or 0)
if not vp or zp>vp then
up,vp=wp,zp
