bs.crit=math.max(bs.crit or 0,(tonumber(Ur.crit)or 0)*as)
end
Ir.aura,Jr=bs,true
elseif Tr.family==Lde[2111]then
local fs=pb.KW[tostring(Tr.keyword or Lde[857])]
local gs=tonumber(Ur.chance)or 1
local hs=tonumber(Ur.secsSeen)or tonumber(Ur.secs)or 5
local js=Ur.keep or Ur.keepSeen
local ks=js and math.min(1,gs*4)or math.min(1,hs*gs/Kr)
if Zr then
ks=math.min(ks,hs/60)
end
if fs and fs.kind==Lde[2101]and not(type(Ur.shred)==Lde[1933])then
local ls=tonumber(Ur.amp)
local ms=Er and((type(Er.ampTypes)==Lde[1933]and Er.ampTypes[fs.dtype])or(tonumber(Er.amp)or 0)>0)
if ls and ls>0 and not ms then
Ir.fx,Jr=(Ir.fx or 0)+ls*V.TYPED_AMP_SHARE*ks*Lr,true
end
elseif fs and(fs.kind==Lde[2048]or fs.kind==Lde[2109])then
if not(Er and((tonumber(Er.stun)or 0)>0 or(tonumber(Er.slowTime)or 0)>0))then
Ir.stun=(fs.kind==Lde[2109]and 0.5 or 1)*hs
if Ur.slow then
Ir.slowP,Ir.slowT=tonumber(Ur.slow),hs
end
Jr=true
end
elseif fs and fs.kind==Lde[2050]then
if not(Er and(tonumber(Er.slowTime)or 0)>0)then
Ir.slowP,Ir.slowT,Jr=tonumber(Ur.slow)or tonumber(Ur.slowSeen)or 0.3,hs,true
end
elseif fs and fs.kind==Lde[2108]then
local ns=tonumber(Ur.dot)or 0
if ns>0 and(tonumber(Er and Er.dot)or 0)<ns*0.5 then
local ps=math.min(1.5,ns)*gs
Ir.dot,Jr=(Ir.dot or 0)+ps,true
if tostring(Tr.keyword)==Lde[1777]then
Ir.burnDot=(Ir.burnDot or 0)+ps
