end
if nC.ice>0 then
local rC=bb.rogueShare(Lde[2064])
oC=oC*(rC+(1-rC)/(1-nC.ice+nC.ice/gb.modFactor(Lde[2461])))
end
if nC.fly>0 then
oC=oC*(1-nC.fly*0.5)
end
if nC.noCC then
oC=oC*0.95
end
if nC.shroud then
oC=oC*0.9
end
if nC.zap then
oC=oC*0.85
