return
end
local uC=bb.huntWeather or mb.weatherNow()
local vC,wC=bb.pred,bb.calRun
if not uC or type(vC)~=Lde[1933]or type(wC)~=Lde[1933]then
return
end
local function xC(yC,zC)
return type(yC)==Lde[1933]and tonumber(yC[zC]or yC[tostring(zC)])or nil
end
local AC={}
for BC=2,bb.wave()do
local CC,DC=xC(wC.alive,BC),xC(vC.aliveAt,BC)
if CC and DC and CC>0 and DC>0 then
table.insert(AC,CC/DC)
end
end
if#AC<3 then
return
end
table.sort(AC)
local EC=AC[math.ceil(#AC/2)]
P.hunt.wk=type(P.hunt.wk)==Lde[1933]and P.hunt.wk or{}
