local HC=mb.weatherK(uC)
local JC=math.max(1,GC)
local KC=math.exp((JC*math.log(HC)+math.log(HC*EC))/(JC+1))
KC=U.clamp(KC,mb.WEATHER_K_MIN,mb.WEATHER_K_MAX)
bb.wkWas={w=tostring(uC),old=FC}
P.hunt.wk[tostring(uC)]={k=KC,n=(type(FC)==Lde[1933]and tonumber(FC.n)or 0)+1,at=os.time()}
F.log(1,Lde[2462],string.format(Lde[2463],tostring(uC),EC,tostring(uC),KC,HC,P.hunt.wk[tostring(uC)].n))
end
