function ib.plan(Aeb,Beb,Ceb)
local Deb=N.session()
local Eeb=table.clone(Ceb)
table.sort(Eeb)
local Feb=table.concat(Eeb,Lde[2780])
local Geb=(tonumber((P.simCal[Aeb.key]or{}).n)or 0)>0
local Heb=Geb and 1.3 or 2
local Ieb=Feb..Lde[2245]..Beb.uuid..(Geb and Lde[3095]or Lde[3096])..Lde[3097]
local Jeb=P.trainSim[Aeb.key]
if Jeb and Jeb.sig==Ieb and not Jeb.pending and os.time()-(Jeb.at or 0)<6*3600 then
return Jeb
end
local Keb={sig=Ieb,base=Feb,uuid=Beb.uuid,at=os.time(),ok=false,margin=Heb,pending=true}
P.trainSim[Aeb.key]=Keb
local Leb,Meb=gb.levelFor(Aeb)
if Aeb.ldOverride then
Leb=Aeb.ldOverride
end
if not Leb then
Keb.why,Keb.pending=Lde[3098],nil
return Keb
end
local Neb=gb.info(Leb,Aeb.key,Meb,Aeb.mod)
local Oeb={}
for Peb,Qeb in ipairs(Ceb)do
local Reb=Deb.collection:get_unit_by_uuid(Qeb)
if Reb then
table.insert(Oeb,Reb)
end
end
local Seb=Deb.collection:get_unit_by_uuid(Beb.uuid)
if not Seb or#Oeb==0 then
Keb.why,Keb.pending=Lde[3099],nil
return Keb
end
local Teb=gb.run(Neb,gb.teamFrom(Oeb,Neb.map),{hpMul=1})
local Ueb=Neb.infinite and gb.unbound(Leb)
local Veb=Ueb and W.infTier(gb.run(Neb,gb.teamFrom(Oeb,Neb.map),{hpMul=Heb}).wave)or nil
local Web={}
for Xeb,Yeb in ipairs(Oeb)do
if not V.isFarm(Yeb.unit_id)then
local Zeb,_eb=pcall(V.score,Yeb,Aeb.mod)
table.insert(Web,{i=Xeb,sc=Zeb and _eb or 0})
end
end
table.sort(Web,function(afb,bfb)
return afb.sc<bfb.sc
end)
local cfb
for dfb=1,math.min(3,#Web)do
local efb=table.clone(Oeb)
efb[Web[dfb].i]=Seb
local ffb=gb.teamFrom(efb,Neb.map)
local gfb=gb.run(Neb,ffb,{hpMul=Heb,train=Beb.uuid})
if(Ueb and W.infTier(gfb.wave)>=Veb)or(not Ueb and gfb.won)then
local hfb=gb.run(Neb,ffb,{hpMul=1,train=Beb.uuid})
local ifb=(hfb.tk or 0)/math.max(0.5,hfb.t/60)
if(hfb.won or Ueb)and(not cfb or ifb>math.max(cfb.rate*1.5,cfb.rate+1))then
cfb={out=Oeb[Web[dfb].i].unit_id,r=hfb,rate=ifb,trial=efb}
end
end
end
Keb.ownMin=Teb.t/60
if not cfb then
Keb.why=Ueb and string.format(Lde[3100],Veb,Geb and Lde[3101]or Lde[3102])or Geb and Lde[3103]or Lde[3104]
else
Keb.out,Keb.tk,Keb.minutes=cfb.out,cfb.r.tk or 0,cfb.r.t/60
Keb.uuids={}
for jfb,kfb in ipairs(cfb.trial)do
table.insert(Keb.uuids,kfb.uuid)
end
Keb.slow=(Teb.won and not Ueb)and Keb.minutes/math.max(0.1,Keb.ownMin)or 1
if Keb.tk<=0 and next(P.train.real)==nil then
Keb.why=Lde[3105]
elseif Keb.slow>ib.SLOW then
Keb.why=string.format(Lde[3106],math.floor((Keb.slow-1)*100+0.5))
else
Keb.ok=true
end
end
Keb.pending=nil
F.log(1,Lde[3107],string.format(Lde[3108],Aeb.label,V.name(Beb.id),Keb.out and(Lde[3109]..V.name(Keb.out))or Lde[857],Keb.ok and string.format(Lde[3110],math.floor((ib.perRun(Aeb.key,Beb.id)or 0)+0.5),Beb.what,Keb.minutes,Keb.ownMin)or tostring(Keb.why)))
F.saveSoon()
return Keb
end
