function eb.upgradeGain(dxb,exb,fxb,gxb,hxb,ixb)
local jxb,kxb=exb[fxb],exb[fxb+1]
local lxb=(jxb.cd>0 and jxb.damage/jxb.cd or 0)
local mxb=(kxb.cd>0 and kxb.damage/kxb.cd or 0)*V.aoe(kxb.atk,kxb.range)/math.max(0.3,V.aoe(jxb.atk,jxb.range))
local nxb=lxb>0 and dxb*(mxb/lxb-1)or(ixb or 0)
local oxb=exb[fxb+2]
if oxb and fxb+1<exb.max and oxb.cd>0 and kxb.cd>0 and lxb>0 then
local pxb=dxb*((oxb.damage/oxb.cd)/lxb-1)
local qxb=gxb+oxb.cost*hxb
if pxb/qxb>nxb/gxb then
nxb=nxb+(pxb/qxb*gxb-nxb)*0.5
end
end
local rxb=(kxb.range or 0)>(jxb.range or 0)and(1+((kxb.range-jxb.range)/math.max(1,jxb.range)))or 1
return math.max(0,nxb)*rxb
end
function eb.dpsFor(sxb,txb)
if txb<=0 then
return 0
end
local uxb={}
for vxb,wxb in ipairs(sxb)do
if not wxb.farm and wxb.gain>0 then
table.insert(uxb,wxb)
end
end
table.sort(uxb,function(xxb,yxb)
return xxb.gain/xxb.cost>yxb.gain/yxb.cost
end)
local zxb,Axb=0,0
for Bxb,Cxb in ipairs(uxb)do
if txb<=0 then
break
end
Axb=Cxb.gain/Cxb.cost
local Dxb=math.min(1,txb/Cxb.cost)
zxb=zxb+Cxb.gain*Dxb
txb=txb-Cxb.cost*Dxb
end
return zxb+math.max(0,txb)*Axb*0.7
end
function eb.shieldDps(Exb,Fxb,Gxb,Hxb,Ixb,Jxb,Kxb)
if(Hxb or 0)<=0 or(Exb or 0)<=0 or(Ixb or 0)<=0 then
return Exb or 0
end
Fxb,Gxb,Jxb=math.max(0.3,Fxb or 2),math.max(1,Gxb or 1),Jxb or 1
local Lxb=Exb*Jxb*Fxb/Gxb
return Ixb*Gxb/((Hxb/math.max(1,Kxb or 1)+math.max(1,Ixb/Lxb))*Fxb)/Jxb
end
function eb.shieldGain(Mxb,Nxb,Oxb,Pxb,Qxb,Rxb,Sxb,Txb)
local Uxb,Vxb=V.attackInfo(Nxb.atk,Nxb.range),V.attackInfo(Pxb.atk,Pxb.range)
local Wxb=eb.shieldDps(Mxb,(tonumber(Nxb.cd)or 2)*(Sxb or 1),Uxb.n,Qxb,Rxb,Txb,Uxb.hits)
local Xxb=eb.shieldDps(Oxb,(tonumber(Pxb.cd)or 2)*(Sxb or 1),Vxb.n,Qxb,Rxb,Txb,Vxb.hits)
local Yxb=math.max(0,((tonumber(Pxb.range)or 0)-(tonumber(Nxb.range)or 0))/math.max(1,tonumber(Nxb.range)or 1))
return math.max(0,Xxb-Wxb)+Wxb*Yxb
end
function eb.shieldWork(Zxb,_xb,ayb,byb,cyb,dyb,eyb,fyb,gyb)
if(byb or 0)<=0 then
return 0
end
local hyb=3*byb*(cyb or 1)/math.max(1,dyb or 20)
if(ayb or 0)>=hyb then
return 0
end
return math.max(1,Zxb or 1)*math.max(1,gyb or 1)/math.max(0.3,_xb or 2)*math.min(eyb or 0,fyb or 0)
end
function eb.holdGain(iyb,jyb,kyb,lyb)
if not iyb or(jyb or 0)<=0 then
return 0
end
local myb,nyb=tonumber(iyb.stun)or 0,tonumber(iyb.slowTime)or 0
if myb<=0 and nyb<=0 then
return 0
end
local oyb,pyb=myb>0 and myb or nyb,myb>0 and 1 or(tonumber(iyb.slowPct)or 0.3)
local qyb=pyb*oyb/(oyb+(tonumber(iyb.ccCd)or 8))
local ryb=qyb/math.max(0.1,1-qyb)
return jyb*ryb*U.clamp(kyb or 0.5,0,1)*math.min(1,(tonumber(iyb.n)or 1)/2)/(1+(lyb or 0))
end
function eb.bleedGain(syb,tyb,uyb,vyb)
if(syb or 0)<=0 then
return 0
end
local wyb=tyb or 0
for xyb,yyb in ipairs(uyb or{})do
wyb=math.max(wyb,(tonumber(yyb.hp)or 0)*0.5)
end
return syb*wyb*(vyb and 0.5 or 1)
end
function eb.bleedShare(zyb,Ayb,Byb,Cyb)
if zyb<=0 or not Ayb then
return 0
end
if Cyb then
return Ayb==0 and zyb or zyb/(Ayb+1)
end
return Byb<Ayb and zyb/(Ayb-Byb)or 0
end
function eb.keepsUp(Dyb,Eyb,Fyb,Gyb,Hyb)
local Iyb=Dyb.coming
if not(Iyb and#Iyb>0 and Dyb.waveSec)then
return true
end
local Jyb=Dyb.eff or 1
local Kyb=Dyb.money-Fyb
local Lyb=(Dyb.teamDps or 0)*(Dyb.shieldK or 1)+(Gyb or 0)*Jyb+eb.dpsFor(Eyb,math.max(0,Kyb))*Jyb
local Myb=(Dyb.farmNow or 0)+(Hyb or 0)
local Nyb=(Dyb.roadSec or 130)*U.clamp(Dyb.cover or 0.6,0.1,1)
local Oyb=Dyb.hpAlive or 0
for Pyb,Qyb in ipairs(Iyb)do
Oyb=math.max(0,Oyb+Qyb.hp-Lyb*Dyb.waveSec)
local Ryb=Lyb*Nyb
if Oyb>Ryb then
return false,Pyb,Ryb/math.max(1,Oyb)
end
if Pyb< #Iyb then
Lyb=Lyb+eb.dpsFor(Eyb,(Qyb.reward or 0)+Myb)*Jyb*(0.85^Pyb)
end
end
return true
end
function eb.decide(Syb,Tyb)
local Uyb=U.clamp(Tyb.cover or 0.6,0.1,1)
local Vyb=math.max(O.clearSec,0.7*(Tyb.roadSec or 50)*Uyb)
local Wyb=(Tyb.clearSec or 0)>Vyb
Tyb.piling=Tyb.piling and Wyb
local Xyb=Tyb.attackers>0 and Tyb.pressure<math.min(O.safeReach,Uyb*0.75)and not Tyb.piling and not Wyb
local Yyb=Tyb.pressure>=math.min(O.dangerReach,Uyb*0.9)or(Tyb.piling and Tyb.enemies>=18)
local Zyb,_yb
for azb,bzb in ipairs(Syb)do
if bzb.farm then
if O.farmUnits and bzb.gain>0 then
bzb.payback=bzb.cost/bzb.gain
if Tyb.left-1>=bzb.payback+(Tyb.farmSpare or O.farmSpare)and(not Zyb or bzb.payback<Zyb.payback)then
Zyb=bzb
end
end
else
bzb.ratio=bzb.gain/math.max(1,bzb.cost)
if not _yb or bzb.ratio>_yb.ratio then
_yb=bzb
end
end
end
if Tyb.leak and Tyb.attackers>0 then
local czb
for dzb,ezb in ipairs(Syb)do
local fzb=not Tyb.airLeak or(ezb.e and bb.cardAir(ezb.e.id))
if ezb.place and not ezb.farm and fzb and ezb.cost<=Tyb.money and not(ezb.e and V.allyBuff(ezb.e.id))and(not czb or ezb.gain>czb.gain)then
czb=ezb
end
end
if czb then
return czb,string.format(Lde[3524],math.floor(Tyb.leak*100))
end
end
local gzb=Tyb.future<Tyb.wantLeft*1.1
local hzb,izb,jzb=true,nil,nil
if Zyb then
hzb,izb,jzb=eb.keepsUp(Tyb,Syb,Zyb.cost,0,Zyb.gain)
end
local kzb=Tyb.coming and not eb.keepsUp(Tyb,Syb,0,0,0)
local lzb=false
if bb.random and Zyb and not Yyb and Tyb.attackers>=2 and Zyb.payback<=Tyb.left/3 then
local mzb=0
for nzb,ozb in ipairs(bb.mine or{})do
if V.isFarm(ozb._stats.id.Value)then
mzb=mzb+1
end
end
lzb=not Zyb.place or mzb<4
end
if kzb and Tyb.attackers>0 then
Yyb=true
end
local pzb=math.max(1,Tyb.incomeRate or 20)
local qzb=Tyb.waveSec or 20
local function rzb(szb,tzb,uzb)
local vzb=math.max(0,(szb.cost-Tyb.money)/pzb)
local wzb=szb.gain*math.max(0,uzb-vzb)
if tzb then
local xzb=math.max(0,Tyb.money-szb.cost)
local yzb=vzb+math.max(0,(tzb.cost-xzb)/pzb)
wzb=wzb+tzb.gain*math.max(0,uzb-yzb)
end
return wzb
end
local zzb,Azb
if Tyb.attackers==0 and _yb then
local Bzb=4*qzb
local Czb={}
for Dzb,Ezb in ipairs(Syb)do
if Ezb.place and not Ezb.farm then
table.insert(Czb,{o=Ezb,v=rzb(Ezb,nil,Bzb)})
end
end
table.sort(Czb,function(Fzb,Gzb)
return Fzb.v>Gzb.v
end)
local Hzb=Tyb.opener and Czb[Tyb.opener]and Tyb.opener or 1
local Izb=Czb[Hzb]and Czb[Hzb].o
zzb,Azb=Izb or _yb,Hzb>1 and Lde[3525]or Lde[3526]
elseif Zyb and Xyb and gzb and not Yyb and hzb then
zzb=Zyb
Azb=string.format(Lde[3527],Zyb.payback,Tyb.left,Tyb.coming and#Tyb.coming or 0)
elseif lzb then
zzb=Zyb
Azb=string.format(Lde[3528],Zyb.payback,Tyb.left)
elseif _yb then
zzb=_yb
if kzb then
Azb=string.format(Lde[3529])
elseif Yyb then
Azb=string.format(Lde[3530],math.floor(Tyb.pressure*100),math.floor(Uyb*100))
elseif Zyb and not hzb then
Azb=string.format(Lde[3531],izb or 1,math.floor((jzb or 0)*100))
elseif Zyb and Wyb then
Azb=string.format(Lde[3532],math.min(999,math.floor(Tyb.clearSec)),math.floor(Vyb))
elseif Zyb and Tyb.piling then
Azb=string.format(Lde[3533],Tyb.enemies)
elseif Zyb and not Xyb then
Azb=Lde[3534]
elseif Zyb and not gzb then
Azb=Lde[3535]
else
Azb=Lde[3536]
end
end
if not zzb then
return nil
end
if zzb.cost>Tyb.money then
local Jzb
if not zzb.farm then
local Kzb=((Tyb.pressure or 0)>=0.95 and 0.5 or Yyb and 2 or 6)*qzb
local Lzb
for Mzb,Nzb in ipairs(Syb)do
if not Nzb.farm and Nzb~=zzb and Nzb.cost<=Tyb.money then
local Ozb=rzb(Nzb,zzb,Kzb)
local Pzb=rzb(zzb,Nzb,Kzb)
if Ozb>Pzb and(not Lzb or Ozb>Lzb)then
Jzb,Lzb=Nzb,Ozb
end
end
end
end
if not Jzb then
return nil,nil,string.format(Lde[3537],U.fmt(zzb.cost),zzb.what or Lde[2166],math.ceil((zzb.cost-Tyb.money)/pzb),math.floor(pzb),Azb),{cost=zzb.cost,what=zzb.what,sec=math.ceil((zzb.cost-Tyb.money)/pzb),rate=math.floor(pzb),why=Azb}
end
zzb,Azb=Jzb,Azb..Lde[3538]
end
return zzb,Azb
end
