function gb.footMove1()
local QLb={}
local function RLb(SLb)
if QLb[SLb]==nil then
local TLb,ULb=0,0
local VLb=P.learn[SLb]
if VLb and tonumber(VLb.n)and VLb.n>=1 then
local WLb=tonumber(VLb.eff)or 1
if(tonumber(VLb.v)or 0)<3 then
WLb=WLb*V.effRescale(SLb)
end
if(tonumber(VLb.v)or 0)<4 then
WLb=WLb*V.secRescale(SLb)
end
TLb,ULb=math.log(math.max(0.01,WLb))*VLb.n,VLb.n
end
local XLb,YLb=V.hiveEff(SLb,true)
if XLb then
TLb,ULb=TLb+math.log(math.max(0.01,XLb))*YLb,ULb+YLb
end
QLb[SLb]=V.nudgeFrom(TLb,ULb)
end
return QLb[SLb]
end
local ZLb=0
for _Lb,aMb in pairs(P.simCal or{})do
for bMb,cMb in ipairs({Lde[3597],Lde[3598]})do
for dMb,eMb in pairs(type(aMb)==Lde[1933]and type(aMb[cMb])==Lde[1933]and aMb[cMb]or{})do
if type(eMb)==Lde[1933]and tonumber(eMb.k)and not tonumber(eMb.nu)then
eMb.nu=RLb(dMb)
ZLb=ZLb+1
end
end
end
end
for fMb in pairs(P.learn or{})do
RLb(fMb)
end
for gMb,hMb in pairs(P.learn or{})do
if type(hMb)==Lde[1933]then
V.learnUp(gMb,hMb)
end
end
P.footV=1
local iMb={}
for jMb,kMb in pairs(QLb)do
local lMb=V.nudge(jMb)
if math.abs(lMb/kMb-1)>=0.05 then
table.insert(iMb,{d=math.abs(math.log(lMb/kMb)),t=string.format(Lde[3601],V.name(jMb),kMb,lMb)})
end
end
table.sort(iMb,function(mMb,nMb)
return mMb.d>nMb.d
end)
local oMb={}
for pMb,qMb in ipairs(iMb)do
if pMb<=8 then
table.insert(oMb,qMb.t)
end
end
F.log(1,Lde[2043],string.format(Lde[3602],#oMb>0 and(Lde[2273]..table.concat(oMb,Lde[2306]))or Lde[857],ZLb))
F.saveSoon()
end
