function jb.sim(fcc,gcc,hcc)
if not O.sim or type(fcc.r._l)~=Lde[1933]then
return nil
end
local icc=tostring(fcc.r._r or(fcc.d..Lde[2066]..fcc.choice))..(gcc and(Lde[2245]..tostring(gcc))or Lde[857])..(hcc and Lde[3802]or Lde[857])
local jcc=jb.data()
