local lcc=W.teamSig()..Lde[2362]..jb.fxText(kcc)..(O.killZone~=false and Lde[3803]or Lde[857])..(bb.forcedWay()and(Lde[2362]..bb.forcedWay())or Lde[857])
local mcc=P.dg.sim[icc]
if mcc and mcc.sig==lcc then
return not mcc.none and mcc or nil
end
