table.insert(ncc,pcc.u)
end
if#ncc==0 then
return nil
end
local qcc=gb.applyFx(gb.info(gb.slim(fcc.r._l),Lde[2641],nil,jb.mod(fcc.r._l)),kcc)
jb.applyK(qcc,fcc.r._r)
if hcc then
qcc.zone=false
end
local rcc=gb.wave(qcc,1,true)
if#rcc==0 then
mcc={none=true,sig=lcc,at=os.time()}
else
local scc=gb.evaluate(qcc,gb.teamFrom(ncc,qcc.map))
mcc={p=scc.p,wave=scc.wave,won=scc.won,total=qcc.total,margin=scc.margin,sig=lcc,at=os.time(),zone=qcc.zone~=false or nil}
end
P.dg.sim[icc]=mcc
if U.count(P.dg.sim)>60 then
local tcc,ucc
for vcc,wcc in pairs(P.dg.sim)do
if not ucc or(wcc.at or 0)<ucc then
tcc,ucc=vcc,wcc.at or 0
end
end
P.dg.sim[tcc]=nil
end
F.saveSoon()
return not mcc.none and mcc or nil
end
function jb.winP(xcc)
