local Ndc=tdc>=3 and 1 or(tdc==2 and 2 or 6)
Ddc.p,Ddc.sim,Ddc.value,Ddc.nextValue,Ddc.nextRoom=Kdc,Ldc,Edc,Fdc or 0,Gdc
Ddc.score=Mdc*(Edc+0.6*(Fdc or 0))-(1-Kdc)*Ndc
