function jb.walletDiff(zfc,Afc)
local Bfc={}
if Afc.gems~=zfc.gems then
table.insert(Bfc,string.format(Lde[3842],Afc.gems-zfc.gems))
end
if Afc.gold~=zfc.gold then
table.insert(Bfc,string.format(Lde[3843],Afc.gold-zfc.gold))
end
for Cfc,Dfc in pairs(Afc.items)do
if Dfc~=(zfc.items[Cfc]or 0)then
table.insert(Bfc,string.format(Lde[3844],Dfc-(zfc.items[Cfc]or 0),tostring(Cfc)))
end
end
for Efc,Ffc in pairs(Afc.units)do
if not zfc.units[Efc]then
table.insert(Bfc,Lde[3845]..V.name(Ffc))
end
end
if Afc.unique~=zfc.unique then
table.insert(Bfc,string.format(Lde[3846],Afc.unique-zfc.unique))
end
return#Bfc>0 and table.concat(Bfc,Lde[2045])or Lde[3847]
end
function jb.openChests(Gfc,Hfc)
local Ifc,Jfc,Kfc=jb.res(Gfc)
local Lfc=jb.lives(Gfc)
local Mfc=jb.cleared(Gfc)
if not(Hfc or Mfc>=jb.ROOMS or Lfc<=1)then
jb.note(string.format(Lde[3848],Mfc,Jfc,Kfc,jb.luck(Gfc)))
F.request(Lde[3834],Lde[3835])
return
end
local Nfc,Ofc,Pfc=0,0,0
local Qfc=tonumber(N.cur(Lde[1997]))or 0
local Rfc=jb.wallet()
for Sfc=1,Jfc+Kfc+4 do
local Tfc,Ufc,Vfc=jb.res(jb.data())
if Ufc+Vfc<=0 or Pfc>=2 then
break
end
local Wfc,Xfc
if Ufc>0 then
Wfc,Xfc=F.request(Lde[3849],Lde[3850])
else
Wfc,Xfc=F.request(Lde[3849],Lde[3850],true)
end
if Wfc and Xfc~=nil then
F.log(1,Lde[3818],Lde[3851]..(type(Xfc)==Lde[1933]and U.json(U.plain(Xfc)):sub(1,300)or tostring(Xfc)))
end
local Yfc=U.now()
while U.now()-Yfc<4 do
local Zfc,_fc,agc=jb.res(jb.data())
if _fc<Ufc or agc<Vfc then
break
end
task.wait(0.25)
end
local bgc,cgc,dgc=jb.res(jb.data())
if cgc<Ufc then
Nfc=Nfc+(Ufc-cgc)
Pfc=0
elseif dgc<Vfc then
Ofc=Ofc+(Vfc-dgc)
Pfc=0
else
Pfc=Pfc+1
end
task.wait(1)
if cgc<Ufc or dgc<Vfc then
local egc=jb.wallet()
local fgc=jb.walletDiff(Rfc,egc)
F.log(1,Lde[3818],(dgc<Vfc and Lde[3852]or Lde[3851])..fgc)
P.dg.pay=P.dg.pay or{}
local ggc={}
for hgc,igc in pairs(egc.items)do
if igc~=(Rfc.items[hgc]or 0)then
ggc[hgc]=igc-(Rfc.items[hgc]or 0)
end
end
table.insert(P.dg.pay,{at=os.time(),rare=dgc<Vfc,gems=egc.gems-Rfc.gems,luck=jb.luck(Gfc),paid=fgc,items=ggc})
while#P.dg.pay>60 do
table.remove(P.dg.pay,1)
end
Rfc=egc
end
end
jb.note(string.format(Lde[3853],Nfc,Ofc,Hfc and Lde[3854]or(Lfc<=1 and Lde[3855]or Lde[3856]),jb.luck(Gfc),(tonumber(N.cur(Lde[1997]))or 0)-Qfc))
local jgc,kgc,lgc=jb.res(jb.data())
if(Hfc or Mfc>=jb.ROOMS)and kgc+lgc>0 then
jb.note(string.format(Lde[3857],kgc,lgc))
W.rec(Lde[2641]).restUntil=os.time()+1800
return Lde[3858]
end
if not Hfc then
F.request(Lde[3834],Lde[3835])
end
end
function jb.act(mgc)
local ngc,ogc=jb.state(mgc)
jb.logState(mgc,ngc)
if ngc==Lde[3817]then
return false
end
if ngc==Lde[3816]then
jb.note(string.format(Lde[3859],tostring(ogc and ogc.t)))
F.request(Lde[3834],Lde[3835])
return true
end
if ngc==Lde[2686]then
F.request(Lde[3860],Lde[3861])
jb.note(Lde[3862])
P.dg.lives,P.dg.lost,P.dg.bailed,P.dg.bails=5,{},{},{}
elseif ngc==Lde[3814]then
if jb.openChests(mgc,true)==Lde[3858]then
return Lde[3858]
end
F.request(Lde[3834],Lde[3835])
local pgc,qgc,rgc=jb.res(jb.data())
table.insert(P.dg.runs,1,{at=os.time(),depth=jb.ROOMS,items=U.count(jb.items(mgc)),left=qgc+rgc})
while#P.dg.runs>10 do
table.remove(P.dg.runs)
end
jb.note(Lde[3863])
elseif ngc==Lde[2959]then
jb.shop(mgc,ogc)
elseif ngc==Lde[3769]then
jb.shrine(mgc,ogc)
elseif ngc==Lde[3815]then
if jb.openChests(mgc,false)==Lde[3858]then
return Lde[3858]
end
end
return true
end
function jb.launch(sgc)
