function bb.buildPath()
bb.samples={}
local okc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not okc then
return
end
for pkc,qkc in pairs(okc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[pkc.Name])then
local rkc={}
for skc,tkc in ipairs(qkc.points or{})do
table.insert(rkc,tkc.part.Position)
end
local ukc=0
for vkc=2,#rkc do
ukc=ukc+(rkc[vkc]-rkc[vkc-1]).Magnitude
end
local wkc=0
for xkc=2,#rkc do
local ykc,zkc=rkc[xkc-1],rkc[xkc]
local Akc=(zkc-ykc).Magnitude
local Bkc=math.max(1,math.floor(Akc/2))
for Ckc=0,Bkc-1 do
local Dkc=ykc:Lerp(zkc,Ckc/Bkc)
table.insert(bb.samples,{pos=Dkc,prog=(wkc+Akc*Ckc/Bkc)/math.max(1,ukc),lane=pkc.Name})
end
wkc=wkc+Akc
end
if rkc[#rkc]then
table.insert(bb.samples,{pos=rkc[#rkc],prog=1,lane=pkc.Name})
end
end
end
pcall(bb.readHidden,okc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local Ekc=tonumber(bb.ld and bb.ld._portal_lanes)
local Fkc=gb.laneList(bb.samples)
if Ekc and Ekc>=1 and Fkc and#Fkc>Ekc then
bb.laneWant=Ekc
end
bb.laneTotal=Fkc and#Fkc or 1
bb.countLanes()
end
function bb.readHidden(Gkc)
local Hkc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(Hkc)~=Lde[1933]or not next(Hkc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local Ikc
for Jkc,Kkc in pairs(Gkc)do
if Hkc[Jkc.Name]and type(Kkc.points)==Lde[1933]and#Kkc.points>=2 then
local Lkc={}
for Mkc,Nkc in ipairs(Kkc.points)do
Lkc[Mkc]=U.flat(Nkc.part.Position)
end
local Okc={}
for Pkc,Qkc in ipairs(bb.samples)do
local Rkc=tostring(Qkc.lane)
Okc[Rkc]=Okc[Rkc]or{}
table.insert(Okc[Rkc],Qkc)
end
local Skc,Tkc
for Ukc,Vkc in pairs(Okc)do
local Wkc=0
for Xkc=1,#Lkc,math.max(1,math.floor(#Lkc/20))do
local Ykc=math.huge
for Zkc,_kc in ipairs(Vkc)do
local alc=(U.flat(_kc.pos)-Lkc[Xkc]).Magnitude
if alc<Ykc then
Ykc=alc
end
end
Wkc=Wkc+Ykc
end
if not Tkc or Wkc<Tkc then
Skc,Tkc=Ukc,Wkc
end
end
local blc,clc,dlc,elc,flc,glc={},nil,nil,nil,0,0
for hlc,ilc in ipairs(Lkc)do
local jlc,klc=nil,math.huge
for llc,mlc in ipairs(Okc[Skc])do
local nlc=(U.flat(mlc.pos)-ilc).Magnitude
if nlc<klc then
klc,jlc=nlc,mlc.prog
end
end
glc=math.max(glc,klc)
if dlc then
local olc=jlc-dlc
local plc=(olc>0.002 and 1)or(olc< -0.002 and-1)or elc
if elc and plc and plc~=elc then
table.insert(blc,math.floor(dlc*1000+0.5)/1000)
end
elc,flc=plc or elc,flc+math.abs(olc)
else
clc=jlc
end
dlc=jlc
if hlc%50==0 then
task.wait()
end
end
if dlc and glc<=8 then
table.insert(blc,math.floor(dlc*1000+0.5)/1000)
Ikc=Ikc or{}
Ikc[Jkc.Name]={from=math.floor((clc or 0)*1000+0.5)/1000,len=math.floor(flc*1000+0.5)/1000,turns=blc,road=Skc}
end
end
end
if not Ikc then
return
end
local qlc=bb.ld.map
P.maps[qlc]=P.maps[qlc]or{}
local rlc=P.maps[qlc].hidden
P.maps[qlc].hidden=Ikc
if type(rlc)~=Lde[1933]then
for slc,tlc in pairs(Ikc)do
F.log(1,Lde[2592],string.format(Lde[3946],slc,tlc.len,tostring(tlc.road),math.floor((#tlc.turns-1)/2)))
end
F.saveSoon()
end
end
function bb.countLanes()
local ulc,vlc,wlc={},0,0
for xlc,ylc in ipairs(bb.samples)do
local zlc=tostring(ylc.lane)
if not ulc[zlc]then
vlc=vlc+1
end
ulc[zlc]=(ulc[zlc]or 0)+1
wlc=wlc+1
end
bb.laneCount={n=vlc,by=ulc,avg=vlc>0 and wlc/vlc or 1}
if vlc>=2 then
local Alc,Blc=pcall(gb.laneSep,bb.samples)
local Clc=P.maps[bb.mapKey()]
if Alc and Blc and type(Clc)==Lde[1933]then
Clc.sep=Blc
end
end
