bb.LANE_WAIT=3
function bb.portalLanes()
if not bb.laneWant or bb.laneCut then
return true
end
if bb.planning then
return false
end
local Dlc,Elc={},0
for Flc,Glc in ipairs(workspace._UNITS:GetChildren())do
local Hlc=Glc:FindFirstChild(Lde[1996])
if Hlc and Hlc:FindFirstChild(Lde[3947])and Hlc.player.Value==nil and Hlc:FindFirstChild(Lde[3948])and Glc:FindFirstChild(Lde[3150])then
local Ilc=tostring(Hlc.lane.Value)
if not Dlc[Ilc]then
Dlc[Ilc]=true
Elc=Elc+1
end
end
end
if Elc==0 then
if U.now()-(bb.startT or U.now())>45 then
bb.laneWant=nil
F.log(1,Lde[2592],Lde[3949])
return true
end
return false
end
bb.laneFirst=bb.laneFirst or U.now()
if Elc<bb.laneWant and U.now()-bb.laneFirst<bb.LANE_WAIT then
return false
end
local Jlc,Klc={},{}
for Llc,Mlc in ipairs(bb.samples)do
if Dlc[tostring(Mlc.lane)]then
table.insert(Jlc,Mlc)
end
end
if#Jlc==0 then
bb.laneWant=nil
return true
end
for Nlc in pairs(Dlc)do
table.insert(Klc,Nlc)
end
table.sort(Klc)
bb.samples,bb.laneCut=Jlc,table.concat(Klc,Lde[2245])
bb.countLanes()
local Olc,Plc=pcall(bb.buildCandidates)
if not Olc then
F.log(1,Lde[2317],Lde[3950]..tostring(Plc))
end
F.log(1,Lde[2592],string.format(Lde[3951],bb.laneWant,bb.laneCut))
if bb.info and O.simSpots and not bb.joinedMid and not bb.random and not bb.infinite and not bb.trialId then
bb.planning=U.now()
task.spawn(function()
local Qlc,Rlc=pcall(bb.planSpots)
bb.planning=nil
if not Qlc then
