end
end)
end
return true
end
function bb.buildWaves()
local Slc=bb.ld
local Tlc=Slc and Slc._dungeon and type(Slc._override_waves)==Lde[1933]and Slc._override_waves or nil
local Ulc=Slc and N.Waves[(Tlc and Tlc.template)or Slc.waves or Slc.id]
local Vlc
if type(Ulc)==Lde[1933]then
Vlc=Ulc.override_waves or Ulc.waves
if not Vlc and Ulc.template and N.Waves[Ulc.template]then
Vlc=N.Waves[Ulc.template].waves or N.Waves[Ulc.template].override_waves
end
end
bb.waveList=U.list(Vlc)
bb.infinite=Slc and(Slc._gamemode==Lde[1952]or Slc.infinite)and gb.unbound(Slc)or false
if bb.infinite then
bb.waveList={}
bb.total=math.max(30,math.floor(W.infReach(bb.key)+0.5))
