end
bb.total=(Slc and type(Slc._dungeon)==Lde[1933]and 15)or tonumber(Slc and Slc._override_infinite_bound_waves)or gb.boundEnd(Slc,#bb.waveList,bb.key)or(#bb.waveList>0 and#bb.waveList)or 15
end
