function bb.infWave(Wlc)
bb.infWaveAt=bb.infWaveAt or{}
bb.infWaveAt[Wlc]=bb.infWaveAt[Wlc]or U.now()
bb.infExtend()
if O.trainLeave and not bb.stopping then
local Xlc,Ylc=pcall(bb.trainLeave,Wlc)
if not Xlc then
F.log(1,Lde[2317],Lde[3953]..tostring(Ylc))
end
end
if O.infiniteStop and not bb.stopping and ab.partyRole()~=Lde[3440]and bb.kind~=Lde[2384]then
local Zlc,_lc=pcall(bb.infStop,Wlc)
if not Zlc then
F.log(1,Lde[2317],Lde[3954]..tostring(_lc))
end
end
local amc=W.infTier(Wlc-1)
if amc<=0 or amc==bb.infTierSeen then
