end
bb.infTierSeen=amc
task.delay(5,function()
if not F.alive then
return
end
local bmc=N.prof()
local cmc=bmc and bmc.daily_infinite_reward_claims and bmc.daily_infinite_reward_claims[bb.ld.id]
local dmc=type(cmc)==Lde[1933]and(tonumber(cmc.highest_claimed_wave)or 0)>=amc and os.time()-(tonumber(cmc.highest_claim_time)or 0)<900
if dmc then
P.infLive=true
end
F.log(1,Lde[2592],string.format(Lde[3955],amc,dmc and Lde[3956]or Lde[3957]))
end)
end
function bb.infStop(emc)
local fmc=0
for gmc,hmc in ipairs(U.list(N.GS.DAILY_INFINITE_REWARDS))do
fmc=math.max(fmc,tonumber(hmc.wave)or 0)
end
if fmc<=0 or emc<=fmc+1 then
return
end
local imc=P.train.on
if bb.trainee and imc and imc.have+(imc.got or 0)+(bb.trainTk or 0)<imc.need then
return
end
if not ab.every(Lde[3958],60)then
return
end
local jmc=W.rec(bb.key)
local kmc=tonumber(jmc.timed)or 0
local lmc=W.INF_PAY
local mmc
if emc>=(lmc.cap+lmc.less)/lmc.per then
mmc=0
else
local nmc=bb.infWaveAt or{}
local omc,pmc=nmc[emc],nmc[emc-5]
if omc and pmc and omc>pmc then
mmc=lmc.per*5/((omc-pmc)/60)
end
if not mmc then
mmc=(kmc>0 and(jmc.sec or 0)>0)and math.max(0.5,(jmc.gems or 0)/(jmc.sec/60))or 2.5
end
end
local qmc=pcall(W.pick)
local rmc
for smc,tmc in ipairs(qmc and W.lastScored or{})do
if tmc.kind~=Lde[1952]and(not rmc or(tmc.score or 0)>(rmc.score or 0))then
rmc=tmc
end
end
if not rmc or(rmc.score or 0)<=mmc then
return
end
bb.stopping=true
F.log(1,Lde[2592],string.format(Lde[3959],emc,mmc,rmc.score,rmc.label))
bb.sellAll()
end
function bb.trainLeave(umc)
local vmc=P.train.on
if not(bb.infinite and bb.trainee and vmc)then
return
end
bb.trainCount()
local wmc=vmc.have+(vmc.got or 0)+(bb.trainTk or 0)
if wmc<vmc.need then
return
end
local xmc,ymc,zmc=pcall(W.infDaily,N.prof(),bb.ld.id,(W.infReach(bb.key)))
if xmc and(ymc or 0)>0 and zmc>0 and umc<=zmc then
