return
end
bb.stopping=true
F.log(1,Lde[2592],string.format(Lde[3961],V.name(vmc.id),vmc.what,U.fmt(wmc),U.fmt(vmc.need),umc))
bb.sellAll()
end
function bb.sellAll()
