table.insert(dnc,{m=jnc,pos=jnc.HumanoidRootPart.Position,prog=rnc,lane=tnc,hp=vnc,red=wnc,fly=ync,soar=znc,sh=Anc,boss=Bnc,uid=knc.id.Value})
