Dnc=Fnc.prog
end
end
bb.waveReach=bb.waveReach or{}
bb.waveReach[Cnc]=math.max(bb.waveReach[Cnc]or 0,Dnc)
end
end)
if not bb.flyerSeen then
for Gnc,Hnc in ipairs(dnc)do
if Hnc.fly then
bb.flyerSeen=math.max(1,bb.wave())
