bb.shieldSeen=true
local Knc=Jnc.m._stats
F.log(1,Lde[2592],string.format(Lde[3970],bb.wave(),tostring(Jnc.sh),tostring(Knc:FindFirstChild(Lde[3971])and Knc.max_shield.Value),tostring(Knc:FindFirstChild(Lde[2308])and Knc.id.Value),Jnc.hp,tostring(bb.info and bb.info.shield)))
break
end
end
end
local Lnc=bb.wave()
local Mnc=0
local Nnc,Onc,Pnc=0,0,0
for Qnc,Rnc in ipairs(dnc)do
Mnc=math.max(Mnc,Rnc.prog)
Nnc=Nnc+Rnc.hp/math.max(0.1,1-Rnc.red)
Pnc=Pnc+Rnc.hp
end
bb.hpAliveRaw=Pnc
for Snc,Tnc in ipairs(enc)do
local Unc=Tnc._stats.id.Value
if not V.isFarm(Unc)and Tnc._stats:FindFirstChild(Lde[2366])then
local Vnc,Wnc=pcall(bb.liveDps,Tnc,Unc)
if Vnc and Wnc then
Onc=Onc+Wnc
end
end
end
bb.hpAlive,bb.teamDps=Nnc,Onc
bb.clearSec=Nnc>0 and(Onc>0 and Nnc/Onc or math.huge)or 0
bb.waveMax[Lnc]=math.max(bb.waveMax[Lnc]or 0,Mnc)
bb.front=Mnc
bb.pressure=math.max(bb.waveMax[Lnc]or 0,bb.waveMax[Lnc-1]or 0)
bb.depth=bb.coverage(enc,dnc)
local Xnc=U.now()
bb.aliveHist=bb.aliveHist or{}
table.insert(bb.aliveHist,{t=Xnc,n= #dnc})
while bb.aliveHist[1]and Xnc-bb.aliveHist[1].t>12 do
table.remove(bb.aliveHist,1)
end
local Ync=bb.aliveHist[1]
bb.piling= #dnc>=8 and Ync and Xnc-Ync.t>=8 and#dnc>Ync.n+1 or false
