end
function bb.blockers()
local loc=os.clock()
if bb.blockersAt and loc-bb.blockersAt<0.5 and bb.blockersList then
return bb.blockersList
end
local moc=game:GetService(Lde[3980])
local noc={}
for ooc,poc in ipairs(bb.mine or{})do
noc[poc]=true
end
local qoc={}
for roc,soc in ipairs({Lde[3962],Lde[3981]})do
