if woc and woc:IsA(Lde[3978])then
local xoc=moc:HasTag(voc,Lde[3983])
if not xoc then
local yoc=voc:FindFirstChild(Lde[1996])
local zoc=yoc and yoc:FindFirstChild(Lde[3947])
local Aoc=yoc and yoc:FindFirstChild(Lde[3965])
xoc=zoc~=nil and zoc.Value~=nil and not(Aoc and Aoc.Value)and yoc:FindFirstChild(Lde[2024])~=nil
end
if xoc then
table.insert(qoc,{p=U.flat(woc.Position),r=math.max(woc.Size.X,woc.Size.Z)/2})
