function bb.valid(Boc,Coc,Doc)
local Eoc=N.PC.raycast(Boc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not Eoc then
return nil
end
if not N.PC.is_valid_raycast_hit(Eoc.Instance,Coc)then
return nil
end
local Foc=Eoc.Position
if bb.blockedSpot(Foc)then
return nil
end
local Goc=(tonumber(Coc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(Goc*2,2.5,Goc*2)
bb.probe.CFrame=CFrame.new(Foc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
local Hoc=U.flat(Foc)
for Ioc,Joc in ipairs(bb.mine or{})do
local Koc=Joc:FindFirstChild(Lde[3982])
local Loc=Koc and Koc.Position or Joc:GetPivot().Position
local Moc=Koc and math.max(Koc.Size.X,Koc.Size.Z)/2 or 1.5
if(Hoc-U.flat(Loc)).Magnitude<Goc+Moc then
return nil
end
end
if not Doc then
for Noc,Ooc in ipairs(bb.blockers())do
if(Hoc-Ooc.p).Magnitude<Goc+Ooc.r then
return nil
end
end
end
return Foc
end
function bb.buildCandidates()
bb.cands={}
local Poc={}
for Qoc=1,#bb.samples,3 do
local Roc=bb.samples[Qoc]
local Soc=bb.samples[math.min(#bb.samples,Qoc+1)]
local Toc=U.flat(Soc.pos-Roc.pos)
if Toc.Magnitude<0.01 then
Toc=Vector3 .new(1,0,0)
end
Toc=Toc.Unit
local Uoc=Vector3 .new(-Toc.Z,0,Toc.X)
for Voc,Woc in ipairs({3,4.5,6,8,10.5,13.5,17})do
for Xoc,Yoc in ipairs({1,-1})do
local Zoc=Roc.pos+Uoc*Woc*Yoc
local _oc=string.format(Lde[3979],math.floor(Zoc.X/1.5),math.floor(Zoc.Z/1.5))
if not Poc[_oc]then
Poc[_oc]=true
table.insert(bb.cands,Zoc)
end
end
end
end
end
function bb.coverage(apc,bpc)
local cpc={}
for dpc,epc in ipairs(apc)do
local fpc=epc._stats
if not V.isFarm(fpc.id.Value)and fpc:FindFirstChild(Lde[2183])then
table.insert(cpc,{p=U.flat(epc:GetPivot().Position),r=fpc.range.Value*(V.SUMMONER[fpc.id.Value]and V.SUMMONER[fpc.id.Value].reach or 1),air=bb.canAir(epc)})
end
end
local gpc,hpc=0,0
if#cpc>0 then
for ipc,jpc in ipairs(bb.samples)do
if jpc.prog>hpc then
local kpc=U.flat(jpc.pos)
for lpc,mpc in ipairs(cpc)do
if(kpc-mpc.p).Magnitude<=mpc.r then
if jpc.prog>gpc then
gpc=jpc.prog
end
if mpc.air then
hpc=jpc.prog
break
end
end
end
end
end
end
local npc,opc={},bb.laneCount
if opc and opc.n>=2 and#cpc>0 then
local ppc={}
for qpc,rpc in ipairs(bb.samples)do
local spc=U.flat(rpc.pos)
for tpc,upc in ipairs(cpc)do
if(spc-upc.p).Magnitude<=upc.r then
local vpc=tostring(rpc.lane)
ppc[vpc]=(ppc[vpc]or 0)+1
if rpc.prog>(npc[vpc]or 0)then
npc[vpc]=rpc.prog
end
break
end
end
end
local wpc,xpc={},0
for ypc,zpc in pairs(opc.by)do
wpc[ypc]=(ppc[ypc]or 0)/math.max(1,zpc)
xpc=math.max(xpc,wpc[ypc])
end
bb.laneW={}
for Apc,Bpc in pairs(opc.by)do
bb.laneW[Apc]=(opc.avg/math.max(1,Bpc))*(1+1.5*(xpc>0 and(1-wpc[Apc]/xpc)or 0))
end
bb.laneFrac=wpc
else
bb.laneW,bb.laneFrac=nil,nil
end
local Cpc,Dpc,Epc
if#cpc>0 then
for Fpc,Gpc in ipairs(bpc)do
local Hpc=(bb.laneW and Gpc.lane)and(npc[tostring(Gpc.lane)]or 0)or gpc
if Gpc.hp>0 and Gpc.prog>Hpc+0.02 and Gpc.prog>(Cpc or 0)then
Cpc,Epc=Gpc.prog,bb.laneW and Gpc.lane or nil
end
if Gpc.hp>0 and Gpc.fly and Gpc.prog>hpc+0.02 then
Dpc=true
end
end
end
local Ipc= #cpc>0 and(bb.pressure or 0)>=gpc-0.08
return{covEnd=gpc,airEnd=hpc,leak=Cpc,leakLane=Epc,covL=npc,airLeak=Dpc,push=Ipc,units= #cpc}
end
function bb.needLastLine(Jpc)
if V.isFarm(Jpc.id)or V.allyBuff(Jpc.id)or bb.fieldCount()<5 then
return false
end
local Kpc,Lpc=0,0
for Mpc,Npc in ipairs(bb.mine or{})do
local Opc=Npc._stats
if not V.isFarm(Opc.id.Value)and Opc:FindFirstChild(Lde[2183])then
local Ppc,Qpc=U.flat(Npc:GetPivot().Position),Opc.range.Value
for Rpc,Spc in ipairs(bb.samples)do
if Spc.prog>=0.85 and(U.flat(Spc.pos)-Ppc).Magnitude<=Qpc then
Kpc=Kpc+1
if bb.canAir(Npc)then
Lpc=Lpc+1
end
break
