bb.airCache=setmetatable({},{__mode=Lde[2316]})
function bb.canAir(Tpc)
local Upc=Tpc._stats:FindFirstChild(Lde[2024])and Tpc._stats.upgrade.Value or 0
local Vpc=bb.airCache[Tpc]
if not Vpc or Vpc.lvl~=Upc then
local Wpc=Tpc:GetAttribute(Lde[3984])==true or Tpc:GetAttribute(Lde[3985])==true
Vpc={lvl=Upc,v=Wpc}
bb.airCache[Tpc]=Vpc
end
return Vpc.v
end
V._airFrom={}
function V.airFrom(Xpc)
local Ypc=V._airFrom[Xpc]
if Ypc~=nil then
return Ypc or nil
end
local Zpc=N.Units[Xpc]
if Zpc and(Zpc.hill_unit or Zpc.hybrid_placement or V.SUMMONER[Xpc])then
V._airFrom[Xpc]=0
return 0
end
local _pc=V.rows(Xpc)
if not(_pc and _pc.max)then
return bb.cardAir(Xpc)and 0 or nil
end
local aqc=false
for bqc=0,_pc.max do
local cqc=_pc[bqc]and _pc[bqc].atk
if cqc and N.Attacks[cqc]and N.Attacks[cqc].targets_flying then
aqc=bqc
break
end
end
if aqc==false and bb.cardAir(Xpc)then
aqc=0
end
V._airFrom[Xpc]=aqc
return aqc or nil
end
function bb.cardAir(dqc)
local eqc=N.Units[dqc]
if not eqc then
return false
end
if eqc.hill_unit or eqc.hybrid_placement then
return true
end
local fqc=V.field(dqc,Lde[2038])or V.field(dqc,Lde[2037])
return fqc and N.Attacks[fqc]and N.Attacks[fqc].targets_flying and true or false
end
function bb.airShare()
local gqc,hqc=0,0
for iqc,jqc in ipairs(bb.mine or{})do
local kqc=jqc._stats.id.Value
if not V.isFarm(kqc)then
local lqc,mqc=pcall(bb.liveDps,jqc,kqc)
mqc=lqc and mqc or 0
gqc=gqc+mqc
if bb.canAir(jqc)then
hqc=hqc+mqc
end
end
end
return gqc>0 and hqc/gqc or 0
end
