bb.sandSold=bb.sandSold or{}
local xqc=(bb.info and tonumber(bb.info.rangeScale))or 1
local function yqc(zqc,Aqc)
for Bqc,Cqc in ipairs(wqc)do
if(U.flat(Cqc.pos)-zqc).Magnitude<=Aqc then
return true
end
end
return false
end
local Dqc={}
for Eqc,Fqc in ipairs(bb.mine or{})do
local Gqc=Fqc:FindFirstChild(Lde[1996])
local Hqc=Gqc and Gqc:FindFirstChild(Lde[2308])and Gqc.id.Value
if Hqc and not V.isFarm(Hqc)and not V.allyBuff(Hqc)and Gqc:FindFirstChild(Lde[2183])then
local Iqc=U.flat(Fqc:GetPivot().Position)
