local Pqc=Oqc and V.allyBuff(Oqc)
local Qqc=Oqc and N.Units[Oqc]
if Pqc and Qqc and not Qqc.unsellable and not bb.sandSold[Mqc]and not V.idol(Oqc)and Nqc:FindFirstChild(Lde[2183])and type(Pqc.types)==Lde[1933]then
local Rqc,Sqc=U.flat(Mqc:GetPivot().Position),tonumber(Nqc.range.Value)or 0
local Tqc,Uqc=false,false
for Vqc,Wqc in ipairs(Dqc)do
if Pqc.types[Wqc.base]then
if(Wqc.p-Rqc).Magnitude<=Sqc then
Tqc=true
break
end
Uqc=true
end
end
if not Tqc and Uqc and not yqc(Rqc,Sqc)then
bb.sandSold[Mqc]=true
local Xqc,Yqc=F.request(Lde[2113],Lde[2311],Mqc)
if Yqc==true then
F.log(1,Lde[3986],string.format(Lde[3987],V.name(Oqc)))
end
return
end
end
end
for Zqc,_qc in ipairs(bb.mine or{})do
local arc=_qc:FindFirstChild(Lde[1996])
local brc=arc and arc:FindFirstChild(Lde[2308])and arc.id.Value
local crc=brc and N.Units[brc]
local drc=arc and arc:FindFirstChild(Lde[2307])and arc.uuid.Value
if crc and not crc.unsellable and not bb.sandSold[brc]and not V.isFarm(brc)and not V.allyBuff(brc)and not V.BLESS.by[brc]and not V.idol(brc)and arc:FindFirstChild(Lde[2183])then
local erc=tonumber(arc.range.Value)or 0
for frc,grc in ipairs(bb.team or{})do
if grc.uuid==drc and grc.u and V.rows(brc)then
erc=math.max(erc,V.range(grc.u,V.rows(brc).max)*xqc)
break
end
end
erc=erc*(V.SUMMONER[brc]and V.SUMMONER[brc].reach or 1)
local hrc,irc=U.flat(_qc:GetPivot().Position),false
for jrc,krc in ipairs(wqc)do
if(U.flat(krc.pos)-hrc).Magnitude<=erc then
irc=true
break
end
end
if not irc then
bb.sandSold[brc]=true
local lrc=arc:FindFirstChild(Lde[3988])and tonumber(arc.total_spent.Value)or 0
local mrc,nrc=F.request(Lde[2113],Lde[2311],_qc)
if nrc==true then
F.log(1,Lde[3986],string.format(Lde[3989],V.name(brc),U.fmt(lrc),math.floor(bb.sandLine()*100+0.5)))
end
return
end
end
end
end
function bb.cover(orc,prc,qrc,rrc,trc)
local urc=0
local vrc=U.flat(orc)
local wrc=qrc and P.maps[bb.mapKey()]and P.maps[bb.mapKey()].dens
local xrc=bb.laneW
for yrc,zrc in ipairs(trc and bb.samples or bb.hurtSamples())do
if(U.flat(zrc.pos)-vrc).Magnitude<=prc then
local Arc=1
if wrc then
Arc=0.15+0.85*(tonumber(wrc[math.min(gb.BINS,math.floor(zrc.prog*gb.BINS)+1)])or 0)
end
if xrc then
Arc=Arc*(xrc[tostring(zrc.lane)]or 1)
end
if rrc then
if rrc.leak and zrc.prog>=rrc.leak-0.01 and(not rrc.leakLane or tostring(zrc.lane)==rrc.leakLane)then
Arc=Arc+3
elseif rrc.push and zrc.prog>rrc.covEnd then
Arc=Arc+0.6
end
end
urc=urc+Arc
end
end
return urc
end
function bb.bleedGain(Brc,Crc,Drc)
