local Krc=Jrc and Jrc:FindFirstChild(Lde[2308])and Jrc.id.Value
local Lrc=Jrc and Jrc:FindFirstChild(Lde[2024])and tonumber(Jrc.upgrade.Value)or 0
if Krc and(V.bleeds(Krc)or 99)<=Lrc then
Grc=true
break
end
end
return eb.bleedShare(eb.bleedGain(Erc,bb.hpAlive or 0,bb.coming,Grc),Frc,Crc,Drc)
end
