bb.STUDY_INF_WAIT=240
function bb.validOpen(RFc,SFc)
local TFc=N.PC.raycast(RFc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not TFc then
return nil
end
if not N.PC.is_valid_raycast_hit(TFc.Instance,SFc)then
return nil
end
local UFc=TFc.Position
if bb.blockedSpot(UFc)then
return nil
end
local VFc=(tonumber(SFc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(VFc*2,2.5,VFc*2)
bb.probe.CFrame=CFrame.new(UFc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return UFc
end
function bb.studyInfinite()
if O.mapStudy==false or not(bb.info and bb.infinite)or bb.kind==Lde[2384]then
return
end
local WFc=bb.info
local function XFc()
return not F.alive or bb.finished or bb.result or F.where~=Lde[2005]or O.mapStudy==false or bb.withOthers or bb.fastAlways
end
local YFc,ZFc={},{}
for _Fc,aGc in ipairs(bb.team or{})do
table.insert(YFc,aGc.u)
if not V.isFarm(aGc.id)and not V.allyBuff(aGc.id)and aGc.uuid~=bb.trainee and V.rows(aGc.id)then
local bGc,cGc=pcall(V.score,aGc.u,bb.mod)
table.insert(ZFc,{e=aGc,id=aGc.id,sc=bGc and cGc or 0})
end
end
if#ZFc==0 then
return
end
table.sort(ZFc,function(dGc,eGc)
return dGc.sc>eGc.sc
end)
local function fGc()
local gGc,hGc={},0
for iGc,jGc in ipairs(ZFc)do
for kGc,lGc in ipairs(bb.mine or{})do
local mGc=lGc:FindFirstChild(Lde[1996])
local nGc=mGc and mGc:FindFirstChild(Lde[2307])
if nGc and nGc.Value==jGc.e.uuid and mGc:FindFirstChild(Lde[2308])and mGc.id.Value==jGc.id then
gGc[jGc.id]=lGc:GetPivot().Position
hGc=hGc+1
break
end
end
end
return gGc,hGc
end
local oGc=U.now()
local pGc,qGc=fGc()
while qGc< #ZFc and U.now()-oGc<bb.STUDY_INF_WAIT do
task.wait(5)
if XFc()then
return
end
pGc,qGc=fGc()
end
if qGc==0 or XFc()then
return
end
local rGc={}
local function sGc(tGc)
local uGc=tGc.hybrid_placement and not tGc.hill_unit
local vGc=uGc and bb.hybridHill
local wGc=((tGc.hill_unit or vGc)and Lde[2701]or(uGc and Lde[4053])or Lde[4054])..Lde[2066]..tostring(tGc.override_hitbox_radius or Lde[857])
if rGc[wGc]then
return rGc[wGc]
end
local xGc={}
local yGc=vGc and bb.hillData(tGc)or tGc
for zGc,AGc in ipairs(bb.cands or{})do
local BGc=bb.validOpen(AGc,yGc)
if BGc then
table.insert(xGc,BGc)
end
if zGc%40==0 then
task.wait()
end
end
rGc[wGc]=xGc
return xGc
end
local CGc={info=WFc,team=gb.teamFrom(YFc,WFc.map),key=bb.bookKey(WFc),hard=1,scale=tonumber(WFc.rangeScale)or 1,attackers={},pauseMax=4,inf=true}
local DGc={spots={},style=Lde[2853],hybridHill=bb.hybridHill and true or false}
for EGc,FGc in ipairs(ZFc)do
local GGc=(gb.holds(FGc.id)and not V.killFed(FGc.id))and true or false
local HGc=GGc and{}or table.clone(sGc(FGc.e.data))
if XFc()then
return
end
local IGc=pGc[FGc.id]
if IGc then
local JGc=bb.nearSpot(HGc,IGc.X,IGc.Z)
if not JGc then
JGc=IGc
table.insert(HGc,IGc)
end
DGc.spots[FGc.id]=JGc
end
if#HGc>0 then
table.insert(CGc.attackers,{id=FGc.id,e=FGc.e,spots=HGc})
end
end
CGc.base=DGc
bb.studyPool=CGc
F.log(1,Lde[2675],string.format(Lde[4118],bb.label(),qGc))
bb.studyRun(CGc)
end
function bb.studyWords(KGc)
if type(KGc)~=Lde[1933]then
return Lde[857]
end
local function LGc(MGc,NGc)
return KGc.kills and string.format(Lde[4063],math.floor((tonumber(MGc)or 0)+0.5))or string.format(Lde[4119],tonumber(NGc)or 0,tonumber(KGc.hp)or 1)
end
return string.format(Lde[4120],tostring(KGc.label),tonumber(KGc.n)or 0,tonumber(KGc.run)or 0,LGc(KGc.bestKills,KGc.bestWave),LGc(KGc.baseKills,KGc.baseWave),(KGc.better or 0)>0 and Lde[4121]or Lde[857])
end
function bb.bookSave(OGc,PGc,QGc,RGc)
P.mapBook=type(P.mapBook)==Lde[1933]and P.mapBook or{}
local SGc={}
for TGc,UGc in pairs(QGc.spots or{})do
SGc[TGc]={math.floor(UGc.X*10+0.5)/10,math.floor(UGc.Y*10+0.5)/10,math.floor(UGc.Z*10+0.5)/10}
end
P.mapBook[PGc.key]={spots=SGc,style=PGc.base.style,hp=RGc.hp,n=RGc.n,kills=QGc.kills and math.floor(QGc.kills+0.5)or nil,wave=QGc.wave and math.floor(QGc.wave*10+0.5)/10 or nil,base=RGc.baseWave and math.floor(RGc.baseWave*10+0.5)/10 or nil,label=RGc.label,map=OGc.map,killScore=RGc.kills,at=os.time()}
local VGc={}
for WGc,XGc in pairs(P.mapBook)do
table.insert(VGc,{k=WGc,at=type(XGc)==Lde[1933]and tonumber(XGc.at)or 0})
end
if#VGc>bb.BOOK_MAX then
table.sort(VGc,function(YGc,ZGc)
return YGc.at>ZGc.at
end)
for _Gc=bb.BOOK_MAX+1,#VGc do
P.mapBook[VGc[_Gc].k]=nil
end
end
F.saveSoon()
end
function bb.studyEnd(aHc,bHc,cHc)
if type(aHc)~=Lde[1933]or aHc.ended then
return
end
aHc.ended=true
if cHc and bHc then
local dHc=bb.bookFor(bHc.info)
if dHc then
dHc.n=aHc.n
F.saveSoon()
elseif aHc.run>0 then
pcall(bb.bookSave,bHc.info,bHc,cHc,aHc)
end
end
if aHc.run>0 then
F.log(1,Lde[2675],bb.studyWords(aHc))
end
end
function bb.studyReport()
local eHc=bb.info and bb.bookFor(bb.info)
if not eHc then
return nil
end
local fHc={}
for gHc,hHc in pairs(eHc.spots)do
if type(hHc)==Lde[1933]then
fHc[gHc]={hHc[1],hHc[3]}
end
end
return{n=eHc.n,kills=eHc.kills,wave=eHc.wave,hp=eHc.hp,spots=fHc}
end
function bb.studyText()
if O.mapStudy==false then
return Lde[2963]
end
if F.where==Lde[2005]and type(bb.study)==Lde[1933]and not bb.study.ended then
return Lde[4122]..bb.studyWords(bb.study)
end
local iHc,jHc,kHc=0,nil,0
for lHc,mHc in pairs(type(P.mapBook)==Lde[1933]and P.mapBook or{})do
if type(mHc)==Lde[1933]then
iHc=iHc+1
if(tonumber(mHc.at)or 0)>kHc then
jHc,kHc=mHc,tonumber(mHc.at)or 0
end
end
end
if iHc==0 then
return Lde[4123]
end
return string.format(Lde[4124],iHc,tostring(jHc.label),tonumber(jHc.n)or 0,jHc.killScore and string.format(Lde[4063],tonumber(jHc.kills)or 0)or string.format(Lde[4125],tostring(jHc.wave)))
end
function bb.spotResult(nHc,oHc)
if not(bb.info and bb.info.timeLimit)then
for pHc,qHc in pairs(bb.layoutUsed or{})do
local rHc=bb.spotRec(pHc,qHc,true)
rHc.runs,rHc.wins=(tonumber(rHc.runs)or 0)+1,(tonumber(rHc.wins)or 0)+(nHc and 1 or 0)
end
end
local sHc,tHc=pcall(bb.labRecord,nHc,oHc)
if not sHc then
F.log(1,Lde[2317],Lde[4112]..tostring(tHc))
end
local uHc,vHc=pcall(bb.layoutResult,nHc,oHc)
if not uHc then
F.log(1,Lde[2317],Lde[4126]..tostring(vHc))
end
if not bb.infinite then
bb.styleRecord(nHc)
end
end
bb.LAYOUT_KEEP,bb.LAYOUT_CONTROL,bb.HIVE_ASIDE,bb.HIVE_LEAD,bb.HIVE_LEAD_MIN=8,2,3600,0.015,300
function bb.layoutRecFor(wHc,xHc)
local yHc=bb.bookKey(wHc)
P.layoutRec=type(P.layoutRec)==Lde[1933]and P.layoutRec or{}
local zHc=P.layoutRec[yHc]
if type(zHc)~=Lde[1933]then
if not xHc then
return nil
end
zHc={at=os.time()}
P.layoutRec[yHc]=zHc
if U.count(P.layoutRec)>80 then
local AHc,BHc
for CHc,DHc in pairs(P.layoutRec)do
local EHc=type(DHc)==Lde[1933]and tonumber(DHc.at)or 0
if not BHc or EHc<BHc then
AHc,BHc=CHc,EHc
end
end
P.layoutRec[AHc]=nil
end
end
return zHc
end
function bb.layoutAdd(FHc,GHc,HHc,IHc,JHc)
FHc.runs,FHc.wins=(tonumber(FHc.runs)or 0)+1,(tonumber(FHc.wins)or 0)+(GHc and 1 or 0)
FHc.sec,FHc.wave=type(FHc.sec)==Lde[1933]and FHc.sec or{},type(FHc.wave)==Lde[1933]and FHc.wave or{}
if GHc and tonumber(HHc)then
table.insert(FHc.sec,math.floor(HHc+0.5))
end
table.insert(FHc.wave,tonumber(IHc)or 0)
if tonumber(JHc)then
FHc.kills=type(FHc.kills)==Lde[1933]and FHc.kills or{}
table.insert(FHc.kills,math.floor(tonumber(JHc)))
while#FHc.kills>bb.LAYOUT_KEEP do
table.remove(FHc.kills,1)
end
end
while#FHc.sec>bb.LAYOUT_KEEP do
table.remove(FHc.sec,1)
end
while#FHc.wave>bb.LAYOUT_KEEP do
table.remove(FHc.wave,1)
end
end
function bb.layoutJudge(KHc,LHc,MHc,NHc)
local OHc,PHc=tonumber(KHc and KHc.runs)or 0,tonumber(LHc and LHc.runs)or 0
if OHc<1 or PHc<bb.LAYOUT_CONTROL then
return nil
end
if NHc and type(KHc.kills)==Lde[1933]and type(LHc.kills)==Lde[1933]and#KHc.kills>=1 and#LHc.kills>=bb.LAYOUT_CONTROL then
local QHc,RHc=bb.labMedian(KHc.kills),bb.labMedian(LHc.kills)
if QHc and RHc and QHc<RHc*0.97 and(#KHc.kills>=2 or QHc<RHc*0.85)then
return string.format(Lde[4127],QHc,RHc)
end
return nil
end
local SHc,THc=(tonumber(KHc.wins)or 0)/OHc,(tonumber(LHc.wins)or 0)/PHc
if not MHc and THc>=0.5 then
if SHc+0.25<THc and(OHc>=2 or(SHc==0 and THc>=0.9 and PHc>=3))then
return string.format(Lde[4128],tonumber(KHc.wins)or 0,OHc,OHc==1 and Lde[857]or Lde[1781],tonumber(LHc.wins)or 0,PHc)
end
local UHc,VHc=bb.labMedian(KHc.sec),bb.labMedian(LHc.sec)
if UHc and VHc and UHc>VHc*1.10 and(#KHc.sec>=2 or UHc>VHc*1.25)then
return string.format(Lde[4129],math.floor(UHc/60),UHc%60,math.floor(VHc/60),VHc%60)
end
return nil
end
local WHc,XHc=bb.labMedian(KHc.wave),bb.labMedian(LHc.wave)
if WHc and XHc and WHc<XHc-math.max(1,XHc*0.03)and(OHc>=2 or WHc<XHc*0.85)then
return string.format(Lde[4130],WHc,XHc)
end
return nil
end
function bb.layoutResult(YHc,ZHc)
local _Hc=bb.info
local aIc=bb.layoutSrc
if not(_Hc and aIc)or bb.labTest or bb.withOthers or bb.fastAlways then
return
end
if bb.infinite and not _Hc.timeLimit then
return
end
local bIc=bb.wave()
local cIc=bb.layoutRecFor(_Hc,true)
cIc.at=os.time()
local dIc=_Hc.timeLimit~=nil
local eIc=_Hc.killScore and true or nil
local fIc=eIc and(bb.killsEnd or bb.realKills())or nil
if aIc==Lde[4100]then
local gIc=bb.bookFor(_Hc)
if not gIc then
return
end
gIc.real=type(gIc.real)==Lde[1933]and gIc.real or{}
bb.layoutAdd(gIc.real,YHc,ZHc,bIc,fIc)
local hIc=gIc.aside==nil and bb.layoutJudge(gIc.real,cIc.own,dIc,eIc)or nil
if hIc then
gIc.aside={at=os.time(),why=hIc}
F.log(1,Lde[4046],string.format(Lde[4131],hIc))
end
else
cIc[aIc]=type(cIc[aIc])==Lde[1933]and cIc[aIc]or{}
local iIc=cIc[aIc]
bb.layoutAdd(iIc,YHc,ZHc,bIc,fIc)
if aIc==Lde[3481]and iIc.aside==nil then
local jIc=bb.layoutJudge(iIc,cIc.own,dIc,eIc)
if jIc then
iIc.aside,iIc.why=os.time(),jIc
F.log(1,Lde[4046],string.format(Lde[4132],jIc))
end
end
end
F.saveSoon()
end
bb.CONTROL_WORDS={Lde[4133],Lde[4134],Lde[4135],Lde[4136]}
function bb.controlSpot(kIc,lIc)
if not bb.killZone()then
return nil
end
local mIc=gb.holds
if not mIc(kIc.id)or V.toggleOf(kIc.id)then
return nil
end
local nIc,oIc,pIc,qIc=1,0,0,{}
local rIc=bb.hurtSamples()
for sIc,tIc in ipairs(bb.mine or{})do
local uIc=tIc._stats
local vIc=uIc.id.Value
if uIc:FindFirstChild(Lde[2183])and not V.isFarm(vIc)and not V.allyBuff(vIc)then
local wIc,xIc=U.flat(tIc:GetPivot().Position),uIc.range.Value
if mIc(vIc)and not V.toggleOf(vIc)then
pIc=pIc+1
table.insert(qIc,{p=wIc,r=xIc})
else
for yIc,zIc in ipairs(rIc)do
if(U.flat(zIc.pos)-wIc).Magnitude<=xIc then
nIc,oIc=math.min(nIc,zIc.prog),math.max(oIc,zIc.prog)
end
end
end
end
end
if oIc<=nIc then
nIc,oIc=0.75,0.98
end
local AIc=(lIc or pIc)+1
local BIc=({nIc,oIc,(nIc+oIc)/2,nIc-(oIc-nIc)/2})[AIc]
if not BIc then
return nil
end
local CIc=V.range(kIc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local DIc={}
for EIc,FIc in ipairs(bb.cands)do
local GIc,HIc,IIc=U.flat(FIc),0,0
for JIc,KIc in ipairs(rIc)do
if(U.flat(KIc.pos)-GIc).Magnitude<=CIc then
IIc=IIc+1
if math.abs(KIc.prog-BIc)<=0.05 then
HIc=HIc+1
local LIc=U.flat(KIc.pos)
for MIc,NIc in ipairs(qIc)do
if(LIc-NIc.p).Magnitude<=NIc.r then
HIc=HIc-0.5
break
end
end
end
end
end
if HIc>0 then
table.insert(DIc,{pos=FIc,sc=HIc,cov=IIc})
end
if EIc%60==0 then
task.wait()
end
end
table.sort(DIc,function(OIc,PIc)
return OIc.sc>PIc.sc
end)
for QIc,RIc in ipairs(DIc)do
local SIc=bb.valid(RIc.pos,kIc.data)
if SIc then
F.log(1,Lde[3986],string.format(Lde[4137],V.name(kIc.id),bb.CONTROL_WORDS[AIc],math.floor(BIc*100+0.5)))
return SIc,RIc.cov,BIc
end
if QIc%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(TIc)
local UIc,VIc=gb.holds(TIc.id)
if not UIc then
return nil
end
if V.killFed(TIc.id)then
return nil
end
local WIc,XIc={},0
for YIc,ZIc in ipairs(bb.mine or{})do
local _Ic=ZIc._stats
local aJc=_Ic.id.Value
if _Ic:FindFirstChild(Lde[2183])and not V.isFarm(aJc)and not V.allyBuff(aJc)and aJc~=TIc.id then
local bJc,cJc=pcall(bb.liveDps,ZIc,aJc)
cJc=bJc and tonumber(cJc)or 0
if cJc>0 then
table.insert(WIc,{p=U.flat(ZIc:GetPivot().Position),r=_Ic.range.Value,d=cJc})
XIc=XIc+cJc
end
end
end
if#WIc==0 or XIc<=0 then
return nil
end
local dJc=bb.hurtSamples()
local eJc={}
for fJc,gJc in ipairs(dJc)do
local hJc,iJc=U.flat(gJc.pos),0
for jJc,kJc in ipairs(WIc)do
if(hJc-kJc.p).Magnitude<=kJc.r then
iJc=iJc+kJc.d
end
end
eJc[fJc]=iJc/XIc
end
local lJc=V.range(TIc.u,math.min(tonumber(VIc)or 0,3,V.rows(TIc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1)
local mJc,nJc,oJc
for pJc,qJc in ipairs(bb.cands)do
local rJc,sJc,tJc=U.flat(qJc),0,0
for uJc,vJc in ipairs(dJc)do
if(U.flat(vJc.pos)-rJc).Magnitude<=lJc then
sJc=sJc+eJc[uJc]
tJc=tJc+1
end
end
if sJc>0 and(not nJc or sJc>nJc)then
local wJc=bb.valid(qJc,TIc.data)
if wJc then
mJc,nJc,oJc=wJc,sJc,tJc
end
end
if pJc%40==0 then
task.wait()
end
end
if not mJc then
return nil
end
bb.holdSaid=bb.holdSaid or{}
if not bb.holdSaid[TIc.id]then
bb.holdSaid[TIc.id]=true
F.log(1,Lde[3986],string.format(Lde[4138],V.name(TIc.id)))
end
return mJc,oJc or 0
end
function bb.bestSpot(xJc,yJc,zJc)
if bb.hybridHill and not xJc._hillTry and type(xJc.data)==Lde[1933]and xJc.data.hybrid_placement and not xJc.data.hill_unit then
local AJc=setmetatable({data=bb.hillData(xJc.data),_hillTry=true},{__index=xJc})
local BJc,CJc,DJc=pcall(bb.bestSpot,AJc,yJc,zJc)
if BJc and CJc then
return CJc,DJc
end
end
if bb.focus and not yJc and not zJc and not V.allyBuff(xJc.id)then
local EJc,FJc=bb.focusSpot(xJc)
if EJc then
return EJc,FJc
end
end
if O.fishiFollow and not yJc and not zJc then
local GJc,HJc,IJc,JJc,KJc=pcall(bb.drownBoss)
if GJc and HJc and not IJc and KJc and KJc[xJc.id]then
local LJc,MJc,NJc=pcall(bb.drownSpot,xJc,HJc)
if LJc and MJc then
return MJc,NJc
end
end
end
if not yJc and not zJc and not(bb.depth and bb.depth.leak)then
local OJc,PJc,QJc=pcall(bb.controlSpot,xJc)
if OJc and PJc then
return PJc,QJc
end
local RJc,SJc,TJc=pcall(bb.holdSpot,xJc)
if RJc and SJc then
return SJc,TJc
end
end
local UJc=bb.depth and bb.depth.leak
if bb.layout and bb.layout[xJc.id]and not yJc and not zJc then
local VJc=false
for WJc,XJc in ipairs(bb.mine or{})do
local YJc=XJc._stats:FindFirstChild(Lde[2307])
if YJc and YJc.Value==xJc.uuid then
VJc=true
break
end
end
if not VJc then
for ZJc,_Jc in ipairs(bb.layout[xJc.id])do
local aKc=bb.valid(_Jc,xJc.data)
if aKc and bb.sandLine()>0 and bb.cover(aKc,V.range(xJc.u,V.rows(xJc.id).max)*((bb.info and tonumber(bb.info.rangeScale))or 1))<=0 then
aKc=nil
end
if aKc and UJc then
local bKc,cKc,dKc=false,U.flat(aKc),V.range(xJc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local eKc=bb.depth and bb.depth.leakLane and tostring(bb.depth.leakLane)or nil
for fKc,gKc in ipairs(bb.hurtSamples())do
if gKc.prog>=UJc+0.02 and(not eKc or tostring(gKc.lane)==eKc)and(U.flat(gKc.pos)-cKc).Magnitude<=dKc then
bKc=true
break
end
end
if not bKc then
aKc=nil
end
end
if aKc then
bb.layoutUsed=bb.layoutUsed or{}
bb.layoutUsed[xJc.id]=aKc
return aKc,bb.cover(aKc,V.range(xJc.u,math.min(3,V.rows(xJc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1))
end
end
end
end
local hKc=xJc.data
local iKc=bb.depth
