function bb.lookAt(qMc)
local rMc,sMc=math.huge,nil
for tMc,uMc in ipairs(bb.samples)do
local vMc=(U.flat(uMc.pos)-U.flat(qMc)).Magnitude
if vMc<rMc then
rMc,sMc=vMc,uMc.pos
end
end
local wMc=sMc and U.flat(sMc-qMc)or Vector3 .new(0,0,-1)
return wMc.Magnitude>0.01 and wMc.Unit or Vector3 .new(0,0,-1)
end
function bb.place(xMc,yMc)
local zMc=V.isFarm(xMc.id)
local AMc,BMc=bb.bestSpot(xMc,zMc or(bb.random and V.idol(xMc.id)),(bb.trainee~=nil and xMc.uuid==bb.trainee)or V.ENTRY[xMc.id]==true or(bb.studyEntry==true and xMc.id==bb.trialId))
if not AMc then
bb.noSpot[xMc.uuid]=(bb.noSpot[xMc.uuid]or 0)+1
F.status(Lde[4049],Lde[4140]..V.name(xMc.id))
