end
local CMc=bb.money()
local DMc=P.caps[xMc.uuid]and bb.count(xMc.uuid)or nil
local EMc,FMc=F.request(Lde[4141],Lde[4142],xMc.uuid,N.Util.CFramePLV(AMc,bb.lookAt(AMc)))
if EMc and FMc then
if DMc and DMc>=(tonumber(P.caps[xMc.uuid])or math.huge)then
F.log(1,Lde[3986],string.format(Lde[4143],V.name(xMc.id),tostring(P.caps[xMc.uuid])))
P.caps[xMc.uuid],P.capsAt[xMc.uuid]=nil,nil
F.saveSoon()
end
bb.spent=bb.spent+(xMc.data.cost or 0)
table.insert(bb.actions,string.format(Lde[4144],V.name(xMc.id)))
F.log(1,Lde[3986],string.format(Lde[4145],V.name(xMc.id),bb.spotKey(AMc),BMc,yMc))
bb.placeLog=bb.placeLog or{}
table.insert(bb.placeLog,{t=math.floor(U.now()-(bb.startT or U.now())),w=bb.wave(),id=xMc.id,x=math.floor(AMc.X),z=math.floor(AMc.Z),cover=math.floor((BMc or 0)+0.5),why=tostring(yMc):sub(1,90)})
F.status(Lde[4049],string.format(Lde[4146],V.name(xMc.id),yMc))
bb.placedAt=bb.placedAt or{}
bb.placedAt[xMc.uuid]=(bb.placedAt[xMc.uuid]or 0)+1
return true
end
if CMc>=(xMc.data.cost or 0)and bb.random then
bb.placeFail=bb.placeFail or{}
bb.placeFail[xMc.uuid]=(bb.placeFail[xMc.uuid]or 0)+1
if bb.placeFail[xMc.uuid]>=2 then
bb.noSpot[xMc.uuid]=3
F.log(1,Lde[3986],string.format(Lde[4147],V.name(xMc.id),bb.fieldCount(),bb.FIELD_MAX))
end
end
if EMc and CMc>=(xMc.data.cost or 0)and not bb.random then
local GMc=bb.spotKey(AMc)
bb.refused[GMc]=true
bb.refusals=(bb.refusals or 0)+1
bb.unitRefusals[xMc.uuid]=(bb.unitRefusals[xMc.uuid]or 0)+1
if not bb.crowded()then
local HMc=bb.mapKey()
P.blocked[HMc]=P.blocked[HMc]or{}
if not bb.refusedRun[GMc]then
P.blocked[HMc][GMc]=(tonumber(P.blocked[HMc][GMc])or 0)+1
bb.refusedRun[GMc]=true
P.blockedAt[HMc]=P.blockedAt[HMc]or{}
P.blockedAt[HMc][GMc]=os.time()
end
if bb.unitRefusals[xMc.uuid]>=3 then
local IMc=math.max(1,bb.count(xMc.uuid))
if P.caps[xMc.uuid]~=IMc or not V.learnedCap(xMc.uuid)then
P.caps[xMc.uuid],P.capsAt[xMc.uuid]=IMc,os.time()
F.log(1,Lde[3986],string.format(Lde[4148],V.name(xMc.id),IMc))
end
end
elseif bb.unitRefusals[xMc.uuid]>=3 and(bb.noSpot[xMc.uuid]or 0)<3 then
bb.noSpot[xMc.uuid]=3
F.log(1,Lde[3986],string.format(Lde[4149],V.name(xMc.id)))
end
if bb.refusals>=bb.REFUSE_FREE then
if not bb.placePause then
