end
bb.placePause=U.now()+bb.REFUSE_PAUSE
end
F.log(2,Lde[3986],Lde[4151]..GMc..Lde[2839]..V.name(xMc.id))
F.saveSoon()
end
return false
end
function bb.crowded()
