if not QMc.start and UMc>0 and#bb.mine==0 then
QMc.start=UMc
end
if TMc~=QMc.lastW then
if bb.trialId and TMc>0 then
bb.trialTrace=bb.trialTrace or{}
local VMc,WMc,XMc,YMc=0,{},0,0
for ZMc,_Mc in ipairs(bb.mine)do
local aNc=_Mc._stats
if aNc.id.Value==bb.trialId then
VMc=VMc+1
table.insert(WMc,tostring(aNc.upgrade.Value))
elseif not V.isFarm(aNc.id.Value)then
YMc=YMc+1
end
end
pcall(bb.sampleHelpers,true)
for bNc,cNc in pairs(bb.ownDealt)do
if cNc.id==bb.trialId then
XMc=XMc+cNc.v
end
end
local dNc=0
for eNc,fNc in pairs(bb.helperDealt)do
if fNc.owner==bb.trialId then
dNc=dNc+fNc.v
end
end
table.insert(bb.trialTrace,string.format(Lde[4152],TMc,SMc-(bb.startT or SMc),UMc,table.concat(WMc,Lde[2780]),YMc,XMc+dNc,#(bb.enemies or{}),bb.hpAliveRaw or 0,bb.waveMax[TMc-1]or 0,bb.teamDps or 0))
end
if QMc.lastW and QMc.lastW>0 and QMc.lastWT then
table.insert(QMc.waveSec,SMc-QMc.lastWT)
end
if QMc.paidT and TMc>0 and SMc-QMc.paidT<15 then
table.insert(QMc.skip,SMc-QMc.paidT)
end
QMc.paidT=nil
if TMc>0 then
QMc.alive[tostring(TMc)]=bb.hpAliveRaw or 0
end
QMc.lastW,QMc.lastWT=TMc,SMc
end
local gNc=workspace:FindFirstChild(Lde[4153])
if gNc and TMc>0 then
QMc.timer[tostring(TMc)]=math.max(QMc.timer[tostring(TMc)]or 0,tonumber(gNc.Value)or 0)
end
local hNc=UMc-(bb.lastMoneyR or UMc)
bb.lastMoneyR=UMc
bb.incomeLog=bb.incomeLog or{}
if hNc>0 then
table.insert(bb.incomeLog,{t=SMc,y=hNc})
end
while bb.incomeLog[1]and SMc-bb.incomeLog[1].t>30 do
table.remove(bb.incomeLog,1)
end
local iNc=0
for jNc,kNc in ipairs(bb.incomeLog)do
iNc=iNc+kNc.y
end
local lNc=math.min(30,SMc-(bb.startT or SMc))
bb.incomeRate=lNc>=8 and iNc/lNc or nil
for mNc,nNc in ipairs(bb.enemies)do
local oNc=nNc.m
local pNc=bb.track[oNc]
if not pNc then
local qNc=oNc._stats
local rNc=oNc:FindFirstChildOfClass(Lde[2326])
local sNc=RMc.cfgById[qNc.id.Value]
local tNc=sNc and gb.baseStats(RMc,sNc)
if rNc and tNc and TMc>0 then
local uNc=tNc*RMc.hpRaw*gb.waveScale(RMc,TMc,RMc.list[TMc])
if uNc>0 and rNc.MaxHealth>0 then
table.insert(QMc.hp,rNc.MaxHealth/uNc)
end
end
bb.track[oNc]={t=SMc,p=nNc.prog,sp=(qNc:FindFirstChild(Lde[4154])and tonumber(qNc.speed.Value))or 1}
if rNc and rNc.MaxHealth>0 then
bb.enemyHpSum=(bb.enemyHpSum or 0)+rNc.MaxHealth
end
if TMc>0 then
QMc.spawn[tostring(TMc)]=(QMc.spawn[tostring(TMc)]or 0)+1
QMc.spawnLast[tostring(TMc)]=SMc-(QMc.lastWT or SMc)
end
elseif not pNc.done and SMc-pNc.t>=15 then
pNc.done=true
local vNc=(nNc.prog-pNc.p)/(SMc-pNc.t)/math.max(0.1,pNc.sp)
if vNc>0.001 and nNc.prog<0.95 then
