local HNc=GNc.id.Value
if not V.isFarm(HNc)and((GNc:FindFirstChild(Lde[4155])and GNc.target.Value~=nil)or bb.inReach(FNc,HNc))then
local INc,JNc=pcall(bb.liveDps,FNc,HNc)
