end
local uRc=bb.buffShort(tRc)
local vRc=P.stack[tRc.attack]
local wRc=vRc and vRc.stacks and(vRc.cap or 1)or nil
local xRc,yRc=pcall(V.range,sRc.u,0)
yRc=(xRc and tonumber(yRc)or 15)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local zRc=wRc and O.community and tonumber(tRc.time)and tonumber(tRc.cd)
local function ARc(BRc,CRc)
local DRc=math.floor(BRc*tRc.time/math.max(1,tRc.cd)+0.001)
