function bb.farmMergePair()
local Wdd={}
for Xdd,Ydd in ipairs(bb.mine or{})do
local Zdd=Ydd._stats.id.Value
if V.isFarm(Zdd)and Ydd._stats:FindFirstChild(Lde[2041])then
Wdd[Zdd]=Wdd[Zdd]or{}
table.insert(Wdd[Zdd],Ydd)
end
end
for _dd,aed in pairs(Wdd)do
if#aed>=2 then
table.sort(aed,function(bed,ced)
return bed._stats.upgrade.Value<ced._stats.upgrade.Value
end)
for ded,eed in ipairs(aed)do
local fed,ged=U.flat(eed:GetPivot().Position),eed._stats.range.Value
local hed,ied=0,0
for jed,ked in ipairs(aed)do
if ked~=eed and(U.flat(ked:GetPivot().Position)-fed).Magnitude<=ged then
hed,ied=hed+(tonumber(ked._stats.farm_amount.Value)or 0),ied+1
end
end
if ied>0 then
return eed,hed,ied
end
end
end
end
end
