bb.trainCount()
local Tfd=bb.trainTk or 0
Sfd.got=(Sfd.got or 0)+Tfd
local Ufd=P.trainSim[Qfd]and tonumber(P.trainSim[Qfd].tk)
if not bb.joinedMid then
local Vfd=P.train.real[Qfd]or{n=0,sum=0}
Vfd.n,Vfd.sum=Vfd.n+1,Vfd.sum+Tfd
P.train.real[Qfd]=Vfd
if Ufd and Ufd>0 then
local Wfd=P.train.cal
Wfd.real,Wfd.sim,Wfd.n=(Wfd.real or 0)+Tfd,(Wfd.sim or 0)+Ufd,(Wfd.n or 0)+1
end
end
table.insert(P.train.log,1,{key=Qfd,got=Tfd,won=Rfd,at=os.time()})
while#P.train.log>20 do
table.remove(P.train.log)
end
F.log(1,Lde[3107],string.format(Lde[4470],V.name(Sfd.id),Tfd,Sfd.what,Rfd and Lde[2666]or Lde[2667],Ufd and string.format(Lde[4471],Ufd)or Lde[857],U.fmt(ib.realHave(Sfd)),U.fmt(Sfd.need)))
