hgd.gems=hgd.gems+mgd
hgd.coins=hgd.coins+ogd
hgd.last=os.time()
local rgd=(hgd.streak or 0)>=O.restAfterLosses and bb.kind~=Lde[1953]and bb.kind~=Lde[2385]and bb.kind~=Lde[2383]and bb.kind~=Lde[2384]and not bb.trialId and not(O.dailyLoop and ggd==Lde[2605])
if rgd then
