end
if not hMd then
iMd.ring.Parent=nil
return
end
iMd.ring.Parent=hMd.ring or hMd.obj
local jMd=hMd.obj:FindFirstAncestorWhichIsA(Lde[5074])
if jMd then
local kMd=hMd.obj.AbsolutePosition.Y-jMd.AbsolutePosition.Y
local lMd,mMd=hMd.obj.AbsoluteSize.Y,jMd.AbsoluteWindowSize.Y
if kMd<0 then
jMd.CanvasPosition=Vector2 .new(0,math.max(0,jMd.CanvasPosition.Y+kMd-10))
elseif kMd+lMd>mMd then
jMd.CanvasPosition=Vector2 .new(0,jMd.CanvasPosition.Y+kMd+lMd-mMd+10)
end
end
end
function nb.K.key(nMd,oMd)
local pMd,qMd,rMd=nb.K,nb.Win,Enum.KeyCode
if pMd.cur and not(pMd.cur.obj and pMd.cur.obj.Parent and pMd.shown(pMd.cur.obj))then
pMd.setFocus(nil)
end
if pMd.cur and pMd.cur.listKey and pMd.cur.listKey(nMd)then
return true
end
if nMd==rMd.PageUp or nMd==rMd.PageDown then
local sMd={}
for tMd,uMd in pairs(qMd._tabs)do
table.insert(sMd,{name=tMd,y=uMd.btn.AbsolutePosition.Y,on=uMd.page.Visible})
end
table.sort(sMd,function(vMd,wMd)
return vMd.y<wMd.y
end)
local xMd=1
for yMd,zMd in ipairs(sMd)do
if zMd.on then
xMd=yMd
end
end
xMd=(xMd-1+(nMd==rMd.PageDown and 1 or-1))% #sMd+1
pMd.setFocus(nil)
qMd:SelectTab(sMd[xMd].name)
return true
end
if nMd==rMd.Tab or nMd==rMd.Down or nMd==rMd.Up then
local AMd=pMd.order()
if#AMd==0 then
return true
end
local BMd=nMd==rMd.Up or(nMd==rMd.Tab and oMd)
local CMd=table.find(AMd,pMd.cur)
if not CMd then
CMd=BMd and#AMd or 1
else
CMd=(CMd-1+(BMd and-1 or 1))% #AMd+1
end
pMd.setFocus(AMd[CMd])
return true
end
if not pMd.cur then
return false
end
if nMd==rMd.Return or nMd==rMd.KeypadEnter or nMd==rMd.Space then
if pMd.cur.activate then
pMd.cur.activate()
end
return true
end
if nMd==rMd.Left or nMd==rMd.Right then
if pMd.cur.adjust then
pMd.cur.adjust(nMd==rMd.Right and 1 or-1)
end
return true
end
if nMd==rMd.Escape then
pMd.setFocus(nil)
return true
end
return false
end
function nb.K.keys(DMd)
