local IMd=Enum.KeyCode
EMd.keyName=Lde[5160]..(tostring(nb.TITLE):gsub(Lde[5161],Lde[857]))
function EMd.over()
local JMd=DMd._main
if not(JMd and JMd.Parent and JMd.Visible)then
return false
end
local KMd=GMd:GetMouseLocation()
local LMd=HMd:GetGuiInset()
local MMd,NMd=KMd.X,KMd.Y-LMd.Y
local OMd,PMd=JMd.AbsolutePosition,JMd.AbsoluteSize
return MMd>=OMd.X and MMd<=OMd.X+PMd.X and NMd>=OMd.Y and NMd<=OMd.Y+PMd.Y
end
FMd:BindActionAtPriority(EMd.keyName,function(QMd,RMd,SMd)
if RMd~=Enum.UserInputState.Begin then
return Enum.ContextActionResult.Pass
end
if GMd:GetFocusedTextBox()or not EMd.over()then
return Enum.ContextActionResult.Pass
end
local TMd,UMd=pcall(EMd.key,SMd.KeyCode,GMd:IsKeyDown(IMd.LeftShift)or GMd:IsKeyDown(IMd.RightShift))
return(TMd and UMd)and Enum.ContextActionResult.Sink or Enum.ContextActionResult.Pass
end,false,3000,IMd.Tab,IMd.Return,IMd.KeypadEnter,IMd.Space,IMd.Left,IMd.Right,IMd.Up,IMd.Down,IMd.Escape,IMd.PageUp,IMd.PageDown)
DMd._track(GMd.InputBegan:Connect(function(VMd)
if VMd.UserInputType==Enum.UserInputType.MouseButton1 and EMd.cur then
pcall(EMd.setFocus,nil)
end
end))
DMd._screen.Destroying:Connect(function()
